class TestCollectCompassClaims:
    def test_empty_compass(self):
        compass = MagicMock(spec=[])  # no directives/axes attrs
        assert _collect_compass_claims(compass) == []

    def test_directives(self):
        d = MagicMock()
        d.kind = "toward"
        d.text = "use dataclasses"
        compass = MagicMock()
        compass.directives = [d]
        del compass.axes  # no axes
        items = _collect_compass_claims(compass)
        assert len(items) == 1
        assert items[0][0] == "use dataclasses"
        assert items[0][1] == 0.7

    def test_axes(self):
        claim = MagicMock()
        claim.text = "pure functions"
        claim.confidence = 0.8
        axis = MagicMock()
        axis.claims = [claim]
        compass = MagicMock()
        del compass.directives
        compass.axes = {"core": axis}
        items = _collect_compass_claims(compass)
        assert len(items) == 1
        assert items[0][0] == "pure functions"


class TestCollectTheoryClaims:
    def test_empty_profile(self):
        assert _collect_theory_claims({}) == []

    def test_dict_claims(self):
        profile = {
            "core": {"claims": [{"text": "claim1", "confidence": 0.9}]},
        }
        items = _collect_theory_claims(profile)
        assert len(items) == 1
        assert items[0][0] == "claim1"
        assert items[0][1] == 0.9

    def test_string_claims(self):
        profile = {"core": {"claims": ["just a string"]}}
        items = _collect_theory_claims(profile)
        assert len(items) == 1
        assert items[0][0] == "just a string"
        assert items[0][1] == 0.7  # default confidence

    def test_non_dict_facet_skipped(self):
        profile = {"core": "not a dict"}
        assert _collect_theory_claims(profile) == []


